function register(doc){const key='m'+String(doc.n).padStart(2,'0');let value=c[key];const modify=val=>{if(!val||typeof val!=='object')return val;val.summary=doc.raw;val.summaryHtml=doc.html;val.updatedAt='2026-11-10';val.summaryOrigin='PDF teórico M01-M15 (10/11/2026)';const ch=val.chapters&&val.chapters.summary;if(Array.isArray(ch)&&ch.length&&doc.heads.length){ch.forEach((x,i)=>{const h=doc.heads;const pos=ch.length===1?0:Math.round(i*(h.length-1)/(ch.length-1));const title=h[pos];x.title=title.replace(/^\d{1,2}(?:\.\d+)?\s+/,'').slice(0,100);x.match=title;});}return val;};if(value)modify(value);try{Object.defineProperty(c,key,{enumerable:true,configurable:true,get(){return value},set(v){value=modify(v);Promise.resolve().then(()=>modify(value))}})}catch(_){/* não altera propriedade não configurável */}}
